import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial, LinearFilter } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new ctx.THREE.Group();

  // --- Atlas region dimensions ---
  const regionW = 512;
  const regionH = 320;
  const planeWidth = 1.5;
  const planeHeight = planeWidth * (regionH / regionW); // ≈0.9375

  // --- Background plane ---
  const geometry = new PlaneGeometry(planeWidth, planeHeight);
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0, // start hidden
  });
  const mesh = new Mesh(geometry, material);
  mesh.frustumCulled = false;
  group.add(mesh);

  // --- Load texture and apply atlas UV offsets ---
  let loadedTexture = null;
  let textureLoadPromise = null;
  if (config.imageUrl) {
    textureLoadPromise = ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      tex.minFilter = LinearFilter;
      tex.magFilter = LinearFilter;

      // Compute UV repeat/offset for the atlas region (source rect starts at 0,0)
      const imgW = tex.image.width;
      const imgH = tex.image.height;
      tex.repeat.set(regionW / imgW, regionH / imgH);
      tex.offset.set(0, 0);
      tex.needsUpdate = true;

      material.map = tex;
      material.needsUpdate = true;

      // Fade-in animation
      gsap.to(material, { opacity: 1, duration: 0.6, ease: 'power2.out' });
    });
  }

  // --- Text label ---
  const textColor = config.colors?.paper || '#e8ecf2';
  // Compute scene-unit font size from 39px based on plane width vs texture width
  // Assume texture width = regionW (if no atlas offset), or use loaded image dimensions if available
  const pxToScene = planeWidth / regionW; // 1.5 / 512 ≈ 0.00293
  const fontSize = 39 * pxToScene; // ≈0.114
  const textMesh = ctx.fontAtlas.createText('Pricing 2', {
    fontSize: fontSize,
    color: textColor,
    align: 'center',
  });
  textMesh.position.z = 0.001; // slightly in front of plane
  group.add(textMesh);

  // --- Event handlers (none) ---
  group.userData.handlers = {};

  // --- Cleanup ---
  group.userData.cleanup = () => {
    // Kill GSAP timelines
    gsap.killTweensOf(material);
    gsap.killTweensOf(textMesh); // in case any

    // Dispose geometry
    geometry.dispose();

    // Dispose material
    if (material.map) {
      material.map.dispose();
    }
    material.dispose();

    // Dispose text resources (traverse and dispose)
    textMesh.traverse((child) => {
      if (child.isMesh) {
        child.geometry.dispose();
        if (child.material) {
          child.material.dispose();
          if (child.material.map) child.material.map.dispose();
        }
      }
    });

    // Remove from parent
    if (group.parent) {
      group.parent.remove(group);
    }
  };

  return group;
}
